import java.util.*;
import java.io.*;

public class Main {
    static final int MOD1 = 998244353;
    static final int MOD2 = 1000000007;
    static final int BASE = 1000000;
    static List<Integer>[] sequence = new ArrayList[7];
    static int[] prefixSum = new int[7];
    static long totalCount, currentOrder, totalAnswer;

    static {
        for (int i = 0; i < 7; i++) {
            sequence[i] = new ArrayList<>();
        }
    }

    static void generateSequences(long start, int level) {
        currentOrder++;
        sequence[level].add((int)((currentOrder - start + MOD1) % MOD1));
        prefixSum[level] = (prefixSum[level] + sequence[level].get(sequence[level].size() - 1)) % MOD2;
        if (level == 6) return;
        for (int digit = 0; digit <= 9; digit++) {
            generateSequences(start * 10 + digit, level + 1);
        }
    }

    static void traverseNumbers(long x) {
        if (x > totalCount) return;
        if (x * BASE + BASE - 1 <= totalCount && x * BASE * 10 > totalCount) {
            long savedOrder = currentOrder;
            for (int i = 0; i <= 6; i++) {
                int size = sequence[i].size();
                int delta = (int)(((savedOrder - x * (long)Math.pow(10, i) + MOD1) % MOD1 + MOD1) % MOD1);
                int pos = lowerBound(sequence[i], (int)(MOD1 - delta));
                totalAnswer = (totalAnswer + 1L * delta * size + prefixSum[i]) % MOD2;
                totalAnswer = (totalAnswer - 1L * (size - pos) * MOD1 + MOD2) % MOD2;
                currentOrder += size;
            }
            return;
        }
        currentOrder++;
        totalAnswer = (totalAnswer + ((currentOrder - x) % MOD1 + MOD1) % MOD1) % MOD2;
        for (int digit = 0; digit <= 9; digit++) {
            traverseNumbers(x * 10 + digit);
        }
    }

    static int lowerBound(List<Integer> list, int value) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= value) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        long n_input = Long.parseLong(br.readLine());
        totalCount = n_input;
        generateSequences(0, 0);
        currentOrder = 0;
        for (int i = 0; i <= 6; i++) {
            Collections.sort(sequence[i]);
        }
        for (int i = 1; i <= 9; i++) {
            traverseNumbers(i);
        }
        System.out.println(totalAnswer);
    }
}
